mapper.select:
select t.trip_type,t.trip_type tripType,t.num_id,t.num_id numId,t.create_time,t.create_time
createTime,t.passenger_id,t.passenger_id passengerId,t.passenger_num,t.passenger_num passengerNum,t.b_id,t.b_id
bId,t.is_self,t.is_self isSelf
from pubcar_trip_car_num t


        t.trip_type= #{tripType}


        and t.num_id= #{numId}


        and t.create_time= #{createTime}


        and t.passenger_id= #{passengerId}


        and t.passenger_num= #{passengerNum}


        and t.status_cd= #{statusCd}


        and t.b_id= #{bId}


        and t.is_self= #{isSelf}


order by t.create_time desc

    limit #{page}, #{row}

